// Content of the public docs site, generated by scripts/gen_docs_site.py from
// app/docs_site.py. Shared by the server pages (static params, metadata) and
// the client view.
import rawSite from "./site.generated.json";

export type Text = { en: string; zh: string };
export type Block =
  | { type: "p" | "h" | "callout"; text: Text; tone?: string }
  | { type: "code"; lang: string; code: string; label: Text | null }
  | { type: "list"; ordered: boolean; items: Text[] }
  | { type: "link"; href: string; text: Text }
  | { type: "table"; columns: Text[]; rows: Text[][] }
  | { type: "markdown"; text: string };
export type Field = { name: string; type: string; required: boolean; description: string };
export type Endpoint = {
  method: string;
  path: string;
  summary: string;
  description: string;
  parameters: Array<Field & { in: string }>;
  body: Field[];
  responses: string[];
};
export type ErrorRow = { code: string; http: number; class: string; rule: string; retryable: boolean };
export type Page = {
  summary: Text;
  blocks: Block[];
  api?: Array<{ group: string; endpoints: Endpoint[] }>;
  errors?: {
    classes: Array<{ class: string; rule: string; action: string }>;
    codes: ErrorRow[];
    warnings: Array<{ code: string; meaning: string }>;
    retry: Record<string, unknown>;
  };
};
export type Site = {
  nav: Array<{ id: string; title: Text; pages: Array<{ slug: string; title: Text }> }>;
  pages: Record<string, Page>;
};

export const site = rawSite as unknown as Site;

export function pageTitle(slug: string, lang: "en" | "zh" = "en"): string {
  for (const group of site.nav) {
    for (const page of group.pages) if (page.slug === slug) return page.title[lang];
  }
  return "Veynod";
}

